#ifndef CRASH_DETECTOR_H
#define CRASH_DETECTOR_H

#include <TensorFlowLite.h>
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/schema/schema_generated.h"

// The converted C-array header generated by export_to_c.py
#include "model_data.h"

class CrashDetector {
public:
    CrashDetector();
    
    // Initializes the TFLite interpreter and allocates memory bounds
    bool begin();
    
    // Feeds 50 sets of 6-axis IMU data into the autoencoder, 
    // calculates MSE, and returns true if it breaches the anomaly threshold.
    bool isCrashDetected(float imu_data[50][6]);
    
    // Helper function to pull the exact MSE error metric for Bluetooth telemetry
    float getLastMSE() const;

private:
    const tflite::Model* model;
    tflite::MicroInterpreter* interpreter;
    TfLiteTensor* input;
    TfLiteTensor* output;
    
    // Allocate 60KB Tensor Arena in standard RAM.
    // 12KB was insufficient for the model's activation buffers during inference.
    // 60KB provides enough headroom for AllocateTensors() to succeed on ESP32.
    static const int kTensorArenaSize = 60 * 1024;
    uint8_t tensor_arena[kTensorArenaSize];
    
    float last_mse;

    // Guard against begin() being called more than once.
    // A static interpreter cannot be safely re-initialized after first use.
    bool initialized;
};

#endif
